1	`timescale 1ns/10ps
2	`include "gemm_s8.v"
3	
4	module tb_gemm_s8;
5	
6	localparam CYCLE = 20;
7	localparam DIM_W = 16;
8	
9	reg                 clk, rst_n, start;
10	reg  [DIM_W-1:0]    M_in, K_in, N_in;
11	reg                 use_bias;
12	wire                done;
13	
14	gemm_s8 #(.DIM_W(DIM_W)) DUT (
15	    .clk(clk), .rst_n(rst_n), .start(start),
16	    .M_in(M_in), .K_in(K_in), .N_in(N_in),
17	    .use_bias(use_bias), .done(done));
18	
19	initial clk = 0; always #(CYCLE/2.0) clk = ~clk;
20	
21	integer M_arg, K_arg, N_arg, bias_arg, fout, k;
22	reg [255:0] a_path, b_path, bias_path, out_path;
23	reg [31:0]  cycles;
24	integer mn;
25	
26	initial begin
27	    if (!$value$plusargs("M=%d", M_arg))      M_arg = 4;
28	    if (!$value$plusargs("K=%d", K_arg))      K_arg = 4;
29	    if (!$value$plusargs("N=%d", N_arg))      N_arg = 4;
30	    if (!$value$plusargs("bias=%d", bias_arg)) bias_arg = 0;
31	    if (!$value$plusargs("a=%s",   a_path))    a_path = "vectors/gemm_a.hex";
32	    if (!$value$plusargs("b=%s",   b_path))    b_path = "vectors/gemm_b.hex";
33	    if (!$value$plusargs("bi=%s",  bias_path)) bias_path = "vectors/gemm_bias.hex";
34	    if (!$value$plusargs("out=%s", out_path))  out_path = "vectors/gemm_out.hex";
35	
36	    M_in = M_arg[DIM_W-1:0];
37	    K_in = K_arg[DIM_W-1:0];
38	    N_in = N_arg[DIM_W-1:0];
39	    use_bias = bias_arg[0];
40	
41	    rst_n = 1; start = 0;
42	    $readmemh(a_path, DUT.a_buf);
43	    $readmemh(b_path, DUT.b_buf);
44	    if (bias_arg) $readmemh(bias_path, DUT.bias_buf);
45	
46	    #(2*CYCLE); rst_n = 0; #(2*CYCLE); rst_n = 1;
47	    @(negedge clk); start = 1; @(negedge clk); start = 0;
48	
49	    cycles = 0;
50	    while (!done) begin
51	        cycles = cycles + 1;
52	        // worst-case: M*K*N + 5*M*N + small overhead
53	        if (cycles > 8 * M_arg * K_arg * N_arg + 100000) begin
54	            $display("TIMEOUT after %0d cycles", cycles); $finish;
55	        end
56	        @(negedge clk);
57	    end
58	
59	    mn = M_arg * N_arg;
60	    fout = $fopen(out_path, "w");
61	    for (k = 0; k < mn; k = k + 1)
62	        $fwrite(fout, "%08x\n", DUT.c_buf[k] & 32'hffffffff);
63	    $fclose(fout);
64	    $display("gemm_s8 OK M=%0d K=%0d N=%0d bias=%0d cycles=%0d",
65	             M_arg, K_arg, N_arg, bias_arg, cycles);
66	    $finish;
67	end
68	
69	endmodule
